Modified to accept a dynamic map of parameters instead of fixed Width/Height arguments.

```typescript
import { Tool, Part, DxfEntity, Point, PlacedTool } from '../types';
import { generateId } from '../utils/helpers';

// Helper to find tool by partial name from script string (e.g. "RECT_3X10 3 32128")
const findToolByPattern = (tools: Tool[], pattern: string): Tool | undefined => {
    if (!pattern) return undefined;
    const cleanName = pattern.split(' ')[0].trim().toUpperCase();
    // Try exact match first (case-insensitive)
    const exact = tools.find(t => t.name.toUpperCase() === cleanName);
    if (exact) return exact;

    // Fallback to partial match if needed
    return tools.find(t => t.name.toUpperCase().includes(cleanName));
};

export const executeParametricScript = (
    basePart: Part, 
    scriptCode: string, 
    tools: Tool[], 
    params: Record<string, number>
): Part => {
    let path = "";
    let currentX = 0;
    let currentY = 0;
    const entities: DxfEntity[] = [];
    const punches: any[] = [];

    // Determine Target Dimensions for BBox
    // We try to look for standard Length/Width or derive them from A/B/C if possible, 
    // but primarily we rely on the script to generate geometry coordinates.
    // We will calculate the true bounding box from the generated entities.

    let targetHeight = params['Width'] || params['Height'] || 100; 
    // If Y is inverted in script (SVG style), we need a reference Height to flip Y back to CAD.
    // We try to infer it. If the script uses "Width" for Y-dimension (common convention in this app), we use it.
    // If script has A,B,C but no Height/Width, we might default or need logic.
    // Assuming generated scripts always provide a Y-dimension variable.

    const PartBuilder = {
        SetMaterial: (code: string, thickness: number) => {
            console.log(`Script SetMaterial: ${code}, ${thickness}`);
        },
        SetControllerIndex: () => {}, 

        StartContour: (x: number, y: number) => {
            path += `M ${x.toFixed(3)} ${y.toFixed(3)} `;
            currentX = x; 
            currentY = y;
        },
        LineTo: (x: number, y: number) => {
            path += `L ${x.toFixed(3)} ${y.toFixed(3)} `;

            entities.push({ 
                type: 'LINE', 
                start: { x: currentX, y: targetHeight - currentY }, 
                end: { x, y: targetHeight - y } 
            });

            currentX = x; 
            currentY = y;
        },
        ArcTo: (endX: number, endY: number, centerX: number, centerY: number, clockwise: boolean) => {
            const radius = Math.sqrt(Math.pow(currentX - centerX, 2) + Math.pow(currentY - centerY, 2));

            const cadCenterY = targetHeight - centerY;
            const cadCurrentY = targetHeight - currentY;
            const cadEndY = targetHeight - endY;

            const startAngle = Math.atan2(cadCurrentY - cadCenterY, currentX - centerX) * 180 / Math.PI;
            const endAngle = Math.atan2(cadEndY - cadCenterY, endX - centerX) * 180 / Math.PI;

            entities.push({
                type: 'ARC',
                center: { x: centerX, y: cadCenterY },
                radius,
                startAngle,
                endAngle
            });

            path += `A ${radius.toFixed(3)} ${radius.toFixed(3)} 0 0 ${clockwise ? 1 : 0} ${endX.toFixed(3)} ${endY.toFixed(3)} `;
            currentX = endX;
            currentY = endY;
        },
        NibbleLine: (toolPattern: string, x1: number, y1: number, x2: number, y2: number, angle: number, pitch: number) => {
            const tool = findToolByPattern(tools, toolPattern);
            if (!tool) return;

            const dist = Math.sqrt(Math.pow(x2 - x1, 2) + Math.pow(y2 - y1, 2));
            const count = Math.max(1, Math.ceil(dist / pitch));
            const dx = (x2 - x1) / count;
            const dy = (y2 - y1) / count;

            const lineId = `script_nibble_${generateId()}`;

            for (let i = 0; i <= count; i++) {
                punches.push({
                    toolId: tool.id,
                    x: x1 + dx * i,
                    y: y1 + dy * i,
                    rotation: angle,
                    lineId: lineId
                });
            }
        },
        Strike: (toolPattern: string, x: number, y: number, angle: number) => {
            const tool = findToolByPattern(tools, toolPattern);
            if (!tool) return;
            punches.push({ toolId: tool.id, x, y, rotation: angle });
        }
    };

    // Dynamic Function Construction
    const paramKeys = Object.keys(params);
    const paramValues = Object.values(params);

    const generateFunc = new Function('Part', 'tools', ...paramKeys, scriptCode);
    generateFunc(PartBuilder, tools, ...paramValues);

    if (!path) {
        throw new Error("Скрипт не сгенерировал геометрию (Part.StartContour ...)");
    }

    const finalPath = path + " Z";
    const generatedPunches: PlacedTool[] = punches.map(p => ({ ...p, id: generateId() }));

    // Recalculate BBox from generated entities to ensure correctness regardless of params
    let minX = Infinity, maxX = -Infinity, minY = Infinity, maxY = -Infinity;
    entities.forEach(e => {
        if(e.type === 'LINE') {
            minX = Math.min(minX, e.start.x, e.end.x);
            maxX = Math.max(maxX, e.start.x, e.end.x);
            minY = Math.min(minY, e.start.y, e.end.y);
            maxY = Math.max(maxY, e.start.y, e.end.y);
        } else if (e.type === 'ARC' || e.type === 'CIRCLE') {
            minX = Math.min(minX, e.center.x - e.radius);
            maxX = Math.max(maxX, e.center.x + e.radius);
            minY = Math.min(minY, e.center.y - e.radius);
            maxY = Math.max(maxY, e.center.y + e.radius);
        }
    });

    // Fallback if empty
    if (minX === Infinity) { minX = 0; maxX = 100; minY = 0; maxY = 100; }

    const calculatedWidth = maxX - minX;
    const calculatedHeight = maxY - minY;

    return {
        ...basePart,
        id: generateId(),
        name: `${basePart.name}_Generated`,
        faceWidth: parseFloat(calculatedWidth.toFixed(2)),
        faceHeight: parseFloat(calculatedHeight.toFixed(2)),
        geometry: {
            path: finalPath,
            width: calculatedWidth,
            height: calculatedHeight,
            entities: entities,
            bbox: { minX, minY, maxX, maxY }
        },
        punches: generatedPunches,
        script: scriptCode
    };
};
```

## services/scriptGenerator.ts

