```typescript
import { Part, Tool, PlacedTool, Point, DxfEntity } from '../types';

export const generateParametricScript = (part: Part, tools: Tool[]): string => {
    const W = part.faceWidth;
    const H = part.faceHeight;
    const { bbox, entities, width: geomWidth, height: geomHeight } = part.geometry;
    const profile = part.profile;

    if (!bbox || !entities) return '// Ошибка: Отсутствует геометрия для генерации скрипта.';

    const fmt = (n: number) => parseFloat(n.toFixed(4)).toString();

    const normalize = (p: Point): Point => ({
        x: p.x - bbox.minX,
        y: geomHeight - (p.y - bbox.minY)
    });

    let pX = (x: number) => fmt(x);
    let headerVars = "";
    let paramHeader = "";

    // --- Strategy Selection ---
    if (profile && profile.type === 'L') {
        const A = profile.dims.a;
        const B = profile.dims.b;

        paramHeader += `// PARAM: A = ${fmt(A)}\n`;
        paramHeader += `// PARAM: B = ${fmt(B)}\n`;
        paramHeader += `// PARAM: Height = ${fmt(H)}\n`;

        headerVars += `const Length = A + B; // Total Unfolded Width\n`;
        headerVars += `const Width = Height;\n`;

        pX = (x: number) => {
            if (Math.abs(x) < 0.001) return '0';
            if (Math.abs(x - geomWidth) < 0.001) return 'Length';
            if (Math.abs(x - A) < 0.001) return 'A'; 

            if (x < A) {
                if (x < A/2) return fmt(x);
                return `A - ${fmt(A - x)}`;
            } else {
                const distFromBend = x - A;
                const distFromRight = geomWidth - x;
                if (distFromBend < distFromRight) return `A + ${fmt(distFromBend)}`;
                return `Length - ${fmt(distFromRight)}`;
            }
        };
    } else if (profile && profile.type === 'U') {
        const A = profile.dims.a;
        const B = profile.dims.b;
        const C = profile.dims.c;
        const srcBend2 = geomWidth - C;

        paramHeader += `// PARAM: A = ${fmt(A)}\n`;
        paramHeader += `// PARAM: B = ${fmt(B)}\n`;
        paramHeader += `// PARAM: C = ${fmt(C)}\n`;
        paramHeader += `// PARAM: Height = ${fmt(H)}\n`;

        headerVars += `const Length = A + B + C; // Total Unfolded Width\n`;
        headerVars += `const Width = Height;\n`;

        pX = (x: number) => {
            if (Math.abs(x) < 0.001) return '0';
            if (Math.abs(x - geomWidth) < 0.001) return 'Length';
            if (Math.abs(x - A) < 0.001) return 'A';
            if (Math.abs(x - srcBend2) < 0.001) return 'Length - C';

            if (x < A) {
                if (x < A/2) return fmt(x);
                return `A - ${fmt(A - x)}`;
            } else if (x > srcBend2) {
                const distFromBend2 = x - srcBend2;
                const distFromRight = geomWidth - x;
                if (distFromBend2 < distFromRight) return `(Length - C) + ${fmt(distFromBend2)}`;
                return `Length - ${fmt(distFromRight)}`;
            } else {
                const distFromBend1 = x - A;
                const distFromBend2 = srcBend2 - x;
                if (distFromBend1 < distFromBend2) return `A + ${fmt(distFromBend1)}`;
                return `(Length - C) - ${fmt(distFromBend2)}`;
            }
        };
    } else {
        // Flat
        paramHeader += `// PARAM: Length = ${fmt(W)}\n`;
        paramHeader += `// PARAM: Width = ${fmt(H)}\n`;

        pX = (x: number): string => {
            const distLeft = x;
            const distRight = geomWidth - x;
            const distCenter = x - geomWidth / 2;

            if (Math.abs(distLeft) < 0.001) return '0';
            if (Math.abs(distRight) < 0.001) return 'Length';
            if (Math.abs(distCenter) < 0.001) return 'Length / 2';

            const isCentral = x > geomWidth * 0.25 && x < geomWidth * 0.75;
            if (isCentral) {
                return distCenter > 0 ? `Length / 2 + ${fmt(distCenter)}` : `Length / 2 - ${fmt(Math.abs(distCenter))}`;
            }
            if (distRight < distLeft) return `Length - ${fmt(distRight)}`;
            return fmt(distLeft);
        };
    }

    const pY = (y: number): string => {
        const distTop = y; 
        const distBottom = geomHeight - y;
        const distCenter = y - geomHeight / 2;

        if (Math.abs(distTop) < 0.001) return '0';
        if (Math.abs(distBottom) < 0.001) return 'Width';
        if (Math.abs(distCenter) < 0.001) return 'Width / 2';

        if (Math.abs(distCenter) < Math.abs(distTop) && Math.abs(distCenter) < Math.abs(distBottom) && Math.abs(distCenter) < (geomHeight / 4)) {
            return distCenter > 0 ? `Width / 2 + ${fmt(distCenter)}` : `Width / 2 - ${fmt(Math.abs(distCenter))}`;
        }
        if (Math.abs(distBottom) < Math.abs(distTop)) return `Width - ${fmt(distBottom)}`;
        return fmt(distTop);
    };

    const dateStr = new Date().toLocaleDateString('ru-RU');
    const profileName = profile?.type === 'L' ? 'L-профиль' : (profile?.type === 'U' ? 'U-профиль' : 'Плоская');

    let script = `// ---------------------------------------------------
// Автоматически сгенерированный скрипт
// Тип: ${profileName}
// Дата: ${dateStr}
// ---------------------------------------------------

${paramHeader}
${headerVars}
// ---------------------------------------------------
// ГЕОМЕТРИЯ
// ---------------------------------------------------
`;

    // --- GEOMETRY CHAINING (Simplified) ---
    type ChainNode = { start: Point; end: Point; entity: DxfEntity; visited: boolean; svgStart: Point; svgEnd: Point; };
    const nodes: ChainNode[] = [];

    entities.forEach(e => {
        if (e.type === 'LINE') {
            nodes.push({ start: e.start, end: e.end, entity: e, visited: false, svgStart: normalize(e.start), svgEnd: normalize(e.end) });
        } else if (e.type === 'LWPOLYLINE') {
            for(let i=0; i<e.vertices.length - (e.closed ? 0 : 1); i++) {
                const p1 = e.vertices[i];
                const p2 = e.vertices[(i+1)%e.vertices.length];
                nodes.push({ start: p1, end: p2, entity: { type: 'LINE', start: p1, end: p2 }, visited: false, svgStart: normalize(p1), svgEnd: normalize(p2) });
            }
        } else if (e.type === 'ARC') {
             const d2r = Math.PI / 180;
             const startRaw = { x: e.center.x + e.radius * Math.cos(e.startAngle * d2r), y: e.center.y + e.radius * Math.sin(e.startAngle * d2r) };
             const endRaw = { x: e.center.x + e.radius * Math.cos(e.endAngle * d2r), y: e.center.y + e.radius * Math.sin(e.endAngle * d2r) };
             nodes.push({ start: startRaw, end: endRaw, entity: e, visited: false, svgStart: normalize(startRaw), svgEnd: normalize(endRaw) });
        } else if (e.type === 'CIRCLE') {
             const c = normalize(e.center);
             const r = e.radius;
             script += `\n\n// Circle (Ø${fmt(r*2)})`;
             script += `\nPart.StartContour(${pX(c.x - r)}, ${pY(c.y)});`;
             script += `\nPart.ArcTo(${pX(c.x + r)}, ${pY(c.y)}, ${pX(c.x)}, ${pY(c.y)}, false);`;
             script += `\nPart.ArcTo(${pX(c.x - r)}, ${pY(c.y)}, ${pX(c.x)}, ${pY(c.y)}, false);`;
        }
    });

    const distSq = (p1: Point, p2: Point) => (p1.x - p2.x)**2 + (p1.y - p2.y)**2;
    const TOLERANCE = 0.01;
    const chains: ChainNode[][] = [];

    while(true) {
        const seed = nodes.find(n => !n.visited);
        if (!seed) break;
        const chain: ChainNode[] = [seed];
        seed.visited = true;
        let tail = seed;
        let finding = true;
        while(finding) {
            const next = nodes.find(n => !n.visited && distSq(tail.end, n.start) < TOLERANCE);
            if (next) { next.visited = true; chain.push(next); tail = next; } 
            else {
                const nextReverse = nodes.find(n => !n.visited && distSq(tail.end, n.end) < TOLERANCE);
                if (nextReverse) {
                    nextReverse.visited = true;
                    const temp = nextReverse.start; nextReverse.start = nextReverse.end; nextReverse.end = temp;
                    const tempSvg = nextReverse.svgStart; nextReverse.svgStart = nextReverse.svgEnd; nextReverse.svgEnd = tempSvg;
                    chain.push(nextReverse); tail = nextReverse;
                } else { finding = false; }
            }
        }
        chains.push(chain);
    }

    const chainStats = chains.map(chain => {
        let minX = Infinity, maxX = -Infinity, minY = Infinity, maxY = -Infinity;
        chain.forEach(n => {
            minX = Math.min(minX, n.svgStart.x, n.svgEnd.x);
            maxX = Math.max(maxX, n.svgStart.x, n.svgEnd.x);
            minY = Math.min(minY, n.svgStart.y, n.svgEnd.y);
            maxY = Math.max(maxY, n.svgStart.y, n.svgEnd.y);
        });
        return { chain, area: (maxX - minX) * (maxY - minY) };
    });
    chainStats.sort((a, b) => b.area - a.area);

    chainStats.forEach((item, index) => {
        const chain = item.chain;
        if (chain.length === 0) return;
        script += `\n\n// Contour ${index+1}`;
        script += `\nPart.StartContour(${pX(chain[0].svgStart.x)}, ${pY(chain[0].svgStart.y)});`;
        chain.forEach(node => {
            const end = node.svgEnd;
            if (node.entity.type === 'LINE') {
                script += `\nPart.LineTo(${pX(end.x)}, ${pY(end.y)});`;
            } else if (node.entity.type === 'ARC') {
                const arc = node.entity as any;
                const c = normalize(arc.center);
                script += `\nPart.ArcTo(${pX(end.x)}, ${pY(end.y)}, ${pX(c.x)}, ${pY(c.y)}, false);`;
            }
        });
    });

    script += `\n\n// ---------------------------------------------------\n// TOOLS\n// ---------------------------------------------------\n`;

    const nibbleGroups = new Map<string, PlacedTool[]>();
    const singlePunches: PlacedTool[] = [];
    part.punches.forEach(p => {
        if (p.lineId) {
            if (!nibbleGroups.has(p.lineId)) nibbleGroups.set(p.lineId, []);
            nibbleGroups.get(p.lineId)?.push(p);
        } else {
            singlePunches.push(p);
        }
    });

    nibbleGroups.forEach((punches) => {
        if (punches.length < 2) { punches.forEach(p => singlePunches.push(p)); return; }
        punches.sort((a, b) => (a.x - b.x) || (a.y - b.y));
        const start = punches[0];
        const end = punches[punches.length - 1];
        const tool = tools.find(t => t.id === start.toolId);
        const toolName = tool ? tool.name : "UNKNOWN";

        // Calc Pitch
        const dx = end.x - start.x;
        const dy = end.y - start.y;
        const dist = Math.sqrt(dx*dx + dy*dy);
        const count = punches.length - 1;
        const pitch = dist / count;

        script += `\nPart.NibbleLine("${toolName}", ${pX(start.x)}, ${pY(start.y)}, ${pX(end.x)}, ${pY(end.y)}, ${start.rotation.toFixed(2)}, ${fmt(pitch)});`;
    });

    singlePunches.forEach(p => {
        const tool = tools.find(t => t.id === p.toolId);
        const toolName = tool ? tool.name : "UNKNOWN";
        script += `\nPart.Strike("${toolName}", ${pX(p.x)}, ${pY(p.y)}, ${p.rotation.toFixed(2)});`;
    });

    return script;
};
