## components/ScriptLibraryView.tsx

Integrate parameter parsing and dynamic inputs.

```typescript
import React, { useState, useEffect } from 'react';
import { ParametricScript, Tool, Part } from '../types';
import { TrashIcon, CodeIcon, SaveIcon, PlusIcon, FileExcelIcon } from './Icons';
import { SidebarTabButton } from './common/Button';
import { executeParametricScript } from '../services/scriptExecutor';
import { generateId } from '../utils/helpers';
import { ExcelImportModal } from './ExcelImportModal';
import { detectPartProfile } from '../services/geometry';
import * as XLSX from 'xlsx';

interface ScriptLibraryViewProps {
    scripts: ParametricScript[];
    tools: Tool[];
    onSaveScript: (script: ParametricScript) => void;
    onDeleteScript: (id: string) => void;
    onCreatePart: (part: Part) => void;
}

interface ScriptParam {
    name: string;
    value: number;
}

export const ScriptLibraryView: React.FC<ScriptLibraryViewProps> = ({ scripts, tools, onSaveScript, onDeleteScript, onCreatePart }) => {
    const [selectedScriptId, setSelectedScriptId] = useState<string | null>(null);
    const [searchQuery, setSearchQuery] = useState('');
    const [activeTab, setActiveTab] = useState<'run' | 'edit'>('run');

    // State for dynamic parameters
    const [params, setParams] = useState<Record<string, number>>({});

    const [previewPart, setPreviewPart] = useState<Part | null>(null);
    const [previewError, setPreviewError] = useState<string | null>(null);

    const [editCode, setEditCode] = useState('');
    const [editName, setEditName] = useState('');
    const [showExcelModal, setShowExcelModal] = useState(false);

    const selectedScript = scripts.find(s => s.id === selectedScriptId);
    const filteredScripts = scripts.filter(s => s.name.toLowerCase().includes(searchQuery.toLowerCase()));

    const parseParamsFromCode = (code: string): Record<string, number> => {
        const paramMap: Record<string, number> = {};
        const regex = /\/\/\s*PARAM:\s*(\w+)\s*=\s*([\d\.]+)/g;
        let match;
        while ((match = regex.exec(code)) !== null) {
            paramMap[match[1]] = parseFloat(match[2]);
        }

        // Fallback for legacy scripts without params: Default to Length/Width
        if (Object.keys(paramMap).length === 0) {
            paramMap['Length'] = 500;
            paramMap['Width'] = 300;
        }
        return paramMap;
    };

    // Initialize when script selected
    useEffect(() => {
        if (selectedScript) {
            const defaults = parseParamsFromCode(selectedScript.code);
            setParams(defaults);
            setEditCode(selectedScript.code);
            setEditName(selectedScript.name);
            generatePreview(selectedScript.code, defaults);
        } else {
            setPreviewPart(null);
        }
    }, [selectedScriptId]);

    const generatePreview = (code: string, currentParams: Record<string, number>) => {
        try {
            const basePart: Part = {
                id: 'temp_preview',
                name: 'Preview',
                faceWidth: currentParams['Length'] || 100, // Approximate fallback
                faceHeight: currentParams['Width'] || currentParams['Height'] || 100,
                geometry: { path: '', width: 100, height: 100, entities: [], bbox: {minX:0,minY:0,maxX:100,maxY:100} },
                punches: [],
                material: { code: 'St-3', thickness: 1, dieClearance: 0.2 },
                nesting: { allow0_180: true, allow90_270: true, initialRotation: 0, commonLine: false, canMirror: false }
            };

            const generated = executeParametricScript(basePart, code, tools, currentParams);
            setPreviewPart(generated);
            setPreviewError(null);
        } catch (e: any) {
            console.error(e);
            setPreviewError(e.message);
            setPreviewPart(null);
        }
    };

    const handleParamChange = (key: string, val: number) => {
        const newParams = { ...params, [key]: val };
        setParams(newParams);
        if (selectedScript) {
            generatePreview(editCode, newParams);
        }
    };

    const handleCreateConcretePart = () => {
        if (previewPart && selectedScript) {
            const newPart = {
                ...previewPart,
                id: generateId(),
                name: `${selectedScript.name}_Generated`
            };
            newPart.profile = detectPartProfile(newPart.geometry);
            onCreatePart(newPart);
        }
    };

    const handleSaveEdit = () => {
        if (selectedScript) {
            onSaveScript({
                ...selectedScript,
                name: editName,
                code: editCode,
                updatedAt: Date.now()
            });
            // Refresh params from new code
            const newDefaults = parseParamsFromCode(editCode);
            setParams(newDefaults);
            generatePreview(editCode, newDefaults);
        }
    };

    const handleExcelProcess = async (file: File) => {
        try {
            const buffer = await file.arrayBuffer();
            const workbook = XLSX.read(buffer);
            const worksheet = workbook.Sheets[workbook.SheetNames[0]];
            const jsonData = XLSX.utils.sheet_to_json(worksheet);

            let successCount = 0;
            let errorCount = 0;

            jsonData.forEach((row: any) => {
                const keys = Object.keys(row);
                const getVal = (k: string) => row[keys.find(key => key.toLowerCase() === k.toLowerCase()) || ''];

                const scriptName = getVal('script');
                const partName = getVal('name');

                if (!scriptName || !partName) {
                    errorCount++;
                    return;
                }

                const targetScript = scripts.find(s => s.name.toLowerCase() === String(scriptName).toLowerCase());
                if (!targetScript) {
                    console.warn(`Script "${scriptName}" not found.`);
                    errorCount++;
                    return;
                }

                // Parse params from script to know what to look for in Excel
                const scriptParams = parseParamsFromCode(targetScript.code);
                const runParams: Record<string, number> = {};

                // Map Excel columns to params
                Object.keys(scriptParams).forEach(paramKey => {
                    const val = parseFloat(getVal(paramKey));
                    runParams[paramKey] = isNaN(val) ? scriptParams[paramKey] : val;
                });

                try {
                    const basePart: Part = {
                        id: generateId(),
                        name: String(partName),
                        faceWidth: 100, faceHeight: 100,
                        geometry: { path: '', width: 100, height: 100, entities: [], bbox: {minX:0,minY:0,maxX:100,maxY:100} },
                        punches: [],
                        material: { code: 'St-3', thickness: 1, dieClearance: 0.2 },
                        nesting: { allow0_180: true, allow90_270: true, initialRotation: 0, commonLine: false, canMirror: false }
                    };
                    const newPart = executeParametricScript(basePart, targetScript.code, tools, runParams);
                    newPart.profile = detectPartProfile(newPart.geometry);
                    onCreatePart(newPart);
                    successCount++;
                } catch (e) {
                    console.error(`Error generating "${partName}":`, e);
                    errorCount++;
                }
            });

            alert(`Импорт завершен.\nСоздано: ${successCount}\nОшибок: ${errorCount}`);
            setShowExcelModal(false);

        } catch (error) {
            alert("Ошибка при чтении файла Excel.");
        }
    };

    return (
        <main className="flex-1 bg-gray-800 flex overflow-hidden h-full" tabIndex={0}>
            {/* Left Panel */}
            <div className="w-1/3 min-w-[300px] flex flex-col border-r border-gray-700 bg-gray-900/30">
                <div className="p-4 border-b border-gray-700 bg-gray-800">
                    <div className="flex justify-between items-center mb-3">
                        <h2 className="text-lg font-bold text-white flex items-center">
                            <CodeIcon className="w-5 h-5 mr-2 text-purple-400" />
                            Библиотека
                        </h2>
                        <button onClick={() => setShowExcelModal(true)} className="text-xs bg-green-700 hover:bg-green-600 text-white px-2 py-1 rounded flex items-center space-x-1">
                            <FileExcelIcon className="w-3 h-3" /><span>Импорт Excel</span>
                        </button>
                    </div>
                    <input type="text" placeholder="Поиск..." value={searchQuery} onChange={(e) => setSearchQuery(e.target.value)} className="w-full bg-gray-900 border border-gray-600 rounded px-3 py-2 text-sm focus:ring-2 focus:ring-purple-500" />
                </div>
                <div className="flex-1 overflow-y-auto divide-y divide-gray-700">
                    {filteredScripts.map(script => (
                        <div key={script.id} onClick={() => setSelectedScriptId(script.id)} className={`p-3 cursor-pointer ${selectedScriptId === script.id ? 'bg-purple-900/50 text-white border-l-4 border-purple-500' : 'hover:bg-gray-700 text-gray-300 border-l-4 border-transparent'}`}>
                            <div className="font-semibold truncate">{script.name}</div>
                        </div>
                    ))}
                </div>
            </div>

            {/* Right Panel */}
            <div className="flex-1 flex flex-col bg-gray-800 relative">
                {selectedScript ? (
                    <div className="flex flex-col h-full">
                        <div className="flex-none p-4 bg-gray-800 border-b border-gray-700 flex justify-between items-center">
                            <h2 className="text-xl font-bold text-white">{editName}</h2>
                            <button onClick={() => { onDeleteScript(selectedScript.id); setSelectedScriptId(null); }} className="text-red-500 hover:text-red-400"><TrashIcon className="w-5 h-5"/></button>
                        </div>
                        <div className="flex border-b border-gray-700 px-4">
                            <SidebarTabButton label="Генератор" active={activeTab === 'run'} onClick={() => setActiveTab('run')} />
                            <SidebarTabButton label="Код" active={activeTab === 'edit'} onClick={() => setActiveTab('edit')} />
                        </div>

                        <div className="flex-1 overflow-hidden flex flex-col">
                            {activeTab === 'run' && (
                                <div className="flex flex-col h-full p-4 space-y-4">
                                    <div className="flex-none bg-gray-700/50 p-4 rounded border border-gray-600">
                                        <h4 className="text-xs font-bold text-gray-400 uppercase mb-3">Параметры</h4>
                                        <div className="grid grid-cols-3 gap-4 mb-4">
                                            {Object.keys(params).map(key => (
                                                <div key={key}>
                                                    <label className="block text-xs text-gray-400 mb-1">{key}</label>
                                                    <input type="number" value={params[key]} onChange={e => handleParamChange(key, parseFloat(e.target.value)||0)} className="bg-gray-900 border border-gray-600 rounded px-2 py-1 w-full" />
                                                </div>
                                            ))}
                                        </div>
                                        <button onClick={handleCreateConcretePart} className="bg-green-600 hover:bg-green-500 text-white px-6 py-2 rounded font-bold shadow-lg flex items-center w-full justify-center">
                                            <PlusIcon className="w-5 h-5 mr-2"/> Создать Деталь
                                        </button>
                                    </div>

                                    <div className="flex-1 bg-gray-900 border-2 border-dashed border-gray-600 rounded flex items-center justify-center relative overflow-hidden">
                                        {previewError ? (
                                            <div className="text-red-400 p-4 text-center"><p className="font-bold">Ошибка:</p><pre className="text-xs mt-2 bg-black/30 p-2 rounded">{previewError}</pre></div>
                                        ) : previewPart ? (
                                            <svg viewBox={`-10 -10 ${previewPart.geometry.width + 20} ${previewPart.geometry.height + 20}`} className="max-w-full max-h-full w-full h-full" preserveAspectRatio="xMidYMid meet">
                                                <path d={previewPart.geometry.path} fill="#2d3748" stroke="#63b3ed" strokeWidth="2" vectorEffect="non-scaling-stroke" />
                                                {previewPart.punches.map((p, i) => <circle key={i} cx={p.x} cy={p.y} r="2" fill="yellow" opacity="0.8" />)}
                                            </svg>
                                        ) : <span className="text-gray-500">Нет данных</span>}
                                    </div>
                                </div>
                            )}

                            {activeTab === 'edit' && (
                                <div className="flex flex-col h-full p-4 space-y-4">
                                    <div className="flex-none">
                                        <label className="block text-xs text-gray-400 mb-1">Название</label>
                                        <input type="text" value={editName} onChange={e => setEditName(e.target.value)} className="w-full bg-gray-900 border border-gray-600 rounded px-3 py-2" />
                                    </div>
                                    <div className="flex-1 flex flex-col">
                                        <label className="block text-xs text-gray-400 mb-1">Код (JS) - Используйте <code>// PARAM: Name = Val</code> для параметров</label>
                                        <textarea value={editCode} onChange={e => { setEditCode(e.target.value); }} className="flex-1 bg-gray-900 font-mono text-sm text-gray-300 p-4 rounded border border-gray-600 outline-none resize-none" spellCheck={false} />
                                    </div>
                                    <div className="flex-none flex justify-end">
                                        <button onClick={handleSaveEdit} className="bg-blue-600 hover:bg-blue-500 text-white px-4 py-2 rounded flex items-center font-bold"><SaveIcon className="w-4 h-4 mr-2"/> Сохранить</button>
                                    </div>
                                </div>
                            )}
                        </div>
                    </div>
                ) : (
                    <div className="flex flex-col items-center justify-center h-full text-gray-500">
                        <CodeIcon className="w-16 h-16 mb-4 opacity-20" /><p className="text-lg">Выберите скрипт</p>
                    </div>
                )}
            </div>
            {showExcelModal && <ExcelImportModal onClose={() => setShowExcelModal(false)} onProcess={handleExcelProcess} />}
        </main>
    );
};
