interface ExcelImportModalProps {
    onClose: () => void;
    onProcess: (file: File) => void;
}

export const ExcelImportModal: React.FC<ExcelImportModalProps> = ({ onClose, onProcess }) => {
    const fileInputRef = useRef<HTMLInputElement>(null);
